<div class="admin-grid-wide"><section class="admin-card"><div class="admin-card-head"><div><h3>Yeni Kampanya</h3><p>Varsayılan kural: ürün için hesaplanan en iyi tek fiyat avantajı uygulanır.</p></div></div><div class="admin-card-body"><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save_campaign"><div class="admin-field full"><label>Kampanya Adı</label><input name="name" required placeholder="Örn. Eylül Kitap Kampanyası"></div><div class="admin-field"><label>Kapsam</label><select name="scope_type"><option value="all">Tüm Site</option><option value="category">Kategori ID</option><option value="brand">Marka ID</option><option value="product">Ürün ID</option></select></div><div class="admin-field"><label>Kapsam ID</label><input type="number" name="scope_id" placeholder="Tüm site için boş"></div><div class="admin-field"><label>İndirim Türü</label><select name="discount_type"><option value="percent">Yüzde İndirim</option><option value="fixed">Sabit TL İndirim</option></select></div><div class="admin-field"><label>İndirim Değeri</label><input type="number" step="0.01" name="discount_value" required></div><div class="admin-field"><label>Minimum Sepet</label><input type="number" step="0.01" name="min_cart_total"></div><div class="admin-field"><label>Minimum Adet</label><input type="number" name="min_qty"></div><div class="admin-field"><label>Başlangıç</label><input type="datetime-local" name="start_at"></div><div class="admin-field"><label>Bitiş</label><input type="datetime-local" name="end_at"></div><div class="check-row full"><label><input type="checkbox" name="is_active" value="1" checked> Aktif</label></div><div class="full"><button class="admin-btn primary large">Kampanyayı Oluştur</button></div></form><div class="id-reference"><div><b>Kategori örnekleri</b><?php foreach(array_slice($cats,0,8) as $c):?><span>#<?=(int)$c['id']?> <?=h($c['name'])?></span><?php endforeach;?></div><div><b>Marka örnekleri</b><?php foreach(array_slice($brands,0,8) as $b):?><span>#<?=(int)$b['id']?> <?=h($b['name'])?></span><?php endforeach;?></div></div></div></section>
<section class="admin-card"><div class="admin-card-head"><div><h3>Kampanyalar</h3><p><?=count($rows)?> kayıt</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Kampanya</th><th>Kapsam</th><th>İndirim</th><th>Minimum</th><th>Tarih</th><th>Durum</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><?=wy_empty('Kampanya yok','İlk kampanyanızı soldaki formdan oluşturun.')?></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><?=h($r['scope_type'])?><?= $r['scope_id']?' #'.(int)$r['scope_id']:''?></td><td><b><?=$r['discount_type']==='percent'?'%'.h($r['discount_value']):money($r['discount_value'])?></b></td><td><?= $r['min_cart_total']!==null?money($r['min_cart_total']):'—'?><?= $r['min_qty']!==null?' / '.(int)$r['min_qty'].' adet':''?></td><td><small><?=h($r['start_at']?:'Hemen')?></small><small><?=h($r['end_at']?:'Süresiz')?></small></td><td><span class="status <?=$r['is_active']?'active':'inactive'?>"><?=$r['is_active']?'Aktif':'Pasif'?></span></td></tr><?php endforeach;?></tbody></table></div></section></div>